set -e
export LANG=C LC_ALL=C
D=/opt/lzh/v7re/work/clk3
rm -rf $D; mkdir -p $D; cd $D
base64 -d << 'EOB' > /tmp/clk3.zip

EOB
unzip -oq /tmp/clk3.zip -d $D
for t in u1_mmcm2mmcm u2_pll2mmcm; do
  /opt/lzh/Xilinx/Vivado/2017.2/bin/vivado -mode batch -notrace -source $t.tcl > $t.log 2>&1
  grep -q DONE_$t $t.log && echo OK $t || { echo FAIL $t; grep -m3 ERROR $t.log; }
done
tar czf /tmp/clk3_out.tgz *.bit *.pips 2>/dev/null || true
echo CLK3DONE
